export function history(initial,limit=100){let states=[JSON.stringify(initial)],index=0;return {push(value){const next=JSON.stringify(value);if(next===states[index])return;states=states.slice(0,index+1);states.push(next);if(states.length>limit)states.shift();index=states.length-1;},undo(){return index>0?JSON.parse(states[--index]):null;},redo(){return index<states.length-1?JSON.parse(states[++index]):null;},get canUndo(){return index>0;},get canRedo(){return index<states.length-1;}};}
export const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
export function resize(box,handle,dx,dy){let {x,y,width,height}=box;if(handle.includes('e'))width=clamp(width+dx,20,10000);if(handle.includes('s'))height=clamp(height+dy,20,10000);if(handle.includes('w')){width=clamp(width-dx,20,10000);x+=box.width-width;}if(handle.includes('n')){height=clamp(height-dy,20,10000);y+=box.height-height;}return {x:clamp(Math.round(x),-10000,10000),y:clamp(Math.round(y),-10000,10000),width:Math.round(width),height:Math.round(height)};}
export function options(e){return {padding:16,gap:12,iconSize:18,align:'center',orientation:'horizontal',showSeconds:false,showDate:false,icon:'',items:e.type==='bar'?[{id:'starter',icon:'◈',label:'Ricing Town',action:'',shortcut:''}]:[],...e.options};}
